pub fn take_any(v: &mut Vec<String>) -> String {
    v[0]
}

pub fn run() -> (String, usize) {
    let mut jobs = vec![
        String::from("resize"),
        String::from("encode"),
        String::from("upload"),
    ];
    let one = take_any(&mut jobs);
    (one, jobs.len())
}

exercises.tests:
