    use super::*;
    #[test]
    fn hands_over_one_job() {
        assert_eq!(run(), (String::from("resize"), 2));
    }
    #[test]
    fn shrinks_the_queue() {
        let mut v = vec![String::from("a"), String::from("b")];
        let got = take_any(&mut v);
        assert_eq!(got, "a");
        assert_eq!(v, vec![String::from("b")]);
    }
}

